add_filter( 'wp_theme_json_data_theme', 'perfectpixel_editor_color_palette' );

function perfectpixel_editor_color_palette( $theme_json ) {
	$palette = array();
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{editor_palette}}' ) ) ) as $i => $entry ) {
		$parts = array_map( 'trim', explode( ':', $entry, 2 ) );
		$color = isset( $parts[1] ) ? sanitize_hex_color( $parts[1] ) : null;
		if ( $color ) {
			// ASCII slugs: CSS custom properties are built from them.
			$palette[] = array( 'name' => $parts[0], 'slug' => 'perfectpixel-' . ( $i + 1 ), 'color' => $color );
		}
	}
	if ( ! $palette ) {
		return $theme_json;
	}
	return $theme_json->update_with(
		array(
			'version'  => 2,
			'settings' => array(
				'color' => array(
					'palette' => $palette,
					'custom'  => 'no' !== strtolower( trim( '{{editor_palette_custom}}' ) ),
				),
			),
		)
	);
}
